import {defaults,scenarios,limits,validateConfig,csvFor,MODEL_VERSION,START} from './simulation.js';
import {optimiseMission} from './optimise.js';
const span=d=>{const a=new Date(START),b=new Date(a.getTime()+(d*24-1)*3600e3),o={day:'numeric',month:'short',timeZone:'UTC'};return `${a.toLocaleDateString('en-GB',o)} – ${b.toLocaleDateString('en-GB',{...o,year:'numeric'})}`;};
const $=s=>document.querySelector(s),fmt=(v,d=0)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config={...defaults},run=null,tab='mission',selected=1,hour=0,busy=false,worker=null,guide=false,dirty=false,error='',activeReject=null,activeAbort=null;
const icons={mission:'◈',dispatch:'⌁',resilience:'◇',model:'≡'};
const navs={mission:'Mission overview',dispatch:'Dispatch explorer',resilience:'Resilience lab',model:'Model & guide'};
const fields=[['days','Mission duration','days'],['fuel','Starting fuel','L'],['solar','Solar capacity','kW'],['wind','Wind capacity','kW'],['battery','Battery capacity','kWh'],['batteryPower','Battery power limit','kW'],['initialSoc','Initial charge','%']];
const palette=['#d99a2b','#0f8f80','#5aa7d8','#8d7fd8'];
function chart(series,{unit='L',labels=['Start','End'],height=230}={}){const W=840,H=height,L=64,R=16,T=18,B=36;const vals=series.flatMap(s=>s.values),min=Math.min(0,...vals),max=Math.max(1,...vals),span=max-min||1;
 const x=(i,n)=>L+i/Math.max(1,n-1)*(W-L-R),y=v=>T+(max-v)/span*(H-T-B);
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series.map(s=>s.name).join(', '))} in ${unit}">`;
 for(let i=0;i<5;i++){const v=min+span*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eaf0"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${fmt(v,Math.abs(v)<10?1:0)}</text>`;}
 series.forEach((s,j)=>{const step=Math.max(1,Math.floor(s.values.length/840));const points=s.values.map((v,i)=>i%step===0||i===s.values.length-1?`${x(i,s.values.length)},${y(v)}`:null).filter(Boolean).join(' ');svg+=`<polyline fill="none" stroke="${s.color||palette[j]}" stroke-width="${s.dash?1.6:2.6}" ${s.dash?'stroke-dasharray="6 5"':'pathLength="1"'} points="${points}"/>`;});
 svg+=`<text x="${L}" y="${H-8}">${esc(labels[0])}</text><text x="${W-R}" y="${H-8}" text-anchor="end">${esc(labels[1])}</text><text x="${L}" y="12">${unit}</text></svg>`;
 return `<div class="chart">${svg}</div><div class="legend">${series.map((s,i)=>`<span><i style="background:${s.color||palette[i]}"></i>${s.name}</span>`).join('')}</div>`;}
function metric(label,value,unit,sub,accent=''){return `<article class="metric ${accent}"><span>${label}</span><strong>${value}<small>${unit}</small></strong><p>${sub}</p></article>`;}
function shell(){document.getElementById('app').innerHTML=`<aside class="rail"><a class="brand" href="#"><span class="monogram">M</span><span>PINK<br><b>MONSTER</b></span></a><div class="rail-label">POLAR ENERGY MANAGEMENT</div><nav aria-label="Main navigation">${Object.entries(navs).map(([id,name])=>`<button data-tab="${id}" class="nav ${tab===id?'active':''}"><span>${icons[id]}</span>${name}</button>`).join('')}</nav><div class="rail-foot"><p>SIH26061</p><small>ERA5 weather · Maitri 2023<br>Software prototype</small><div class="rail-rule"></div><button class="text-btn" id="guideToggle">${guide?'Close':'Open'} companion guide ↗</button></div></aside><div class="workspace"><header class="topbar"><span>Station operations <span class="muted">/ Mission console</span></span><div><span class="pill">SIMULATION MODE</span><button id="downloadGuide" class="small-btn">Build guide ↓</button></div></header><main><div class="page-title"><div><div class="eyebrow">TEAM PINK MONSTER <span> / </span> ${String(Object.keys(navs).indexOf(tab)+1).padStart(2,'0')}</div><h1>${navs[tab]}</h1><p>${{mission:'Plan the polar winter. Keep critical power on.',dispatch:'Trace every hour from weather to the final dispatch.',resilience:'Test the plan when conditions stop cooperating.',model:'A transparent model, with a clear path to the final build.'}[tab]}</p></div><div class="title-actions"><button id="csv" class="secondary" ${!run?'disabled':''}>Hourly CSV ↓</button><button id="json" class="secondary" ${!run?'disabled':''}>Full run JSON ↓</button></div></div><div id="status" role="status" aria-live="polite"></div><div class="content-layout ${guide?'with-guide':''}"><div id="surface"></div>${guide?`<aside class="companion"><div class="eyebrow">GUIDE ALONGSIDE YOUR DEMO</div><h2>Walk through the mission</h2><ol><li>Keep 30 days and run the simulation.</li><li>Compare fuel, all unserved demand and battery end state.</li><li>Open dispatch. Select an hour and trace the power balance.</li><li>Run the four-day blizzard. Solar and wind become zero during its window.</li><li>Try generator failure and a missed renewable lull.</li><li>Inspect the fuel allowance and carry-forward balance.</li><li>Export CSV / JSON and show the model limits.</li></ol><div class="note">Weather is ERA5 reanalysis for Maitri, 2023. Solar, wind and station demand come from the engine's physics model of the station.</div><a href="./BUILD_GUIDE.md" download>Download full Markdown guide ↓</a></aside>`:''}</div><footer>Pink Monster · Fuel-survivability EMS <span>1-hour steps · Model ${MODEL_VERSION} · ${run?.execution==='python-milp'?'Python MILP':'Browser simulation'}</span></footer></main></div>`;
 $('.brand').onclick=e=>{e.preventDefault();tab='mission';shell();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;shell();});$('#guideToggle').onclick=()=>{guide=!guide;shell();};$('#downloadGuide').onclick=()=>downloadUrl('./BUILD_GUIDE.md');$('#csv').onclick=()=>download('pink-monster-hourly.csv',csvFor(run),'text/csv');$('#json').onclick=()=>download('pink-monster-run.json',JSON.stringify(run,null,2),'application/json');surface();}
function controls(){return `<aside class="panel settings"><div class="panel-title"><h2>Station configuration</h2><button id="reset" class="text-btn">Reset</button></div><label class="field wide">Mission scenario<select id="scenario">${Object.entries(scenarios).map(([k,v])=>`<option value="${k}" ${config.scenario===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="fields">${fields.map(([k,label,unit])=>`<label class="field">${label}<div class="input-unit"><input id="${k}" type="number" min="${limits[k][0]}" max="${limits[k][1]}" step="${k==='days'?1:'any'}" value="${config[k]}" required><span>${unit}</span></div></label>`).join('')}</div><label class="field wide">Browser fallback reserve setting<select id="risk"><option value="0" ${config.risk===0?'selected':''}>Lean · browser fallback</option><option value="1" ${config.risk===1?'selected':''}>Balanced · browser fallback</option><option value="2" ${config.risk===2?'selected':''}>Conservative · browser fallback</option></select></label><div class="hardware"><span>FIXED DIESEL PLANT</span><strong>60 kW <span>+</span> 125 kW</strong><small>MILP: both units allowed · 30% minimum load</small></div><button id="simulate" class="primary" ${busy?'disabled':''}>${busy?'Simulating…':'Run simulation'} <span>→</span></button>${busy?'<button id="cancel" class="secondary full">Cancel run</button>':''}<p class="settings-note">Both controllers receive the same actual weather, demand and starting resources.</p></aside>`;}
function surface(){if(!run){$('#surface').innerHTML=`<div class="panel"><h2>${error?'Unable to load the initial run':'Preparing the mission…'}</h2><p>${esc(error||'Loading a reproducible example computed by the included simulation engine.')}</p><button id="fresh" class="primary">Run a fresh simulation</button></div>`;$('#fresh').onclick=()=>startRun();status();return;}
 const content=tab==='mission'?mission():tab==='dispatch'?dispatchView():tab==='resilience'?resilience():model();$('#surface').innerHTML=content;bindSurface();status();enhance();}
function status(){const node=$('#status');if(!node)return;node.innerHTML=error?`<div class="notice error">${esc(error)}</div>`:busy?'<div class="notice" id="progress">Computing both controllers…</div>':dirty?'<div class="notice">Configuration changed. Results still show the previous run. Select Run simulation to update.</div>':run?.warning?`<div class="notice error">${esc(run.warning)}</div>`:run?.execution==='python-milp'?'<div class="notice">Connected to FastAPI · Python MILP results · 24-hour quantile forecasts · uncertainty reserve · clean-air preference · hard fuel limit.</div>':'<div class="notice">Browser simulation example. Run simulation to connect to FastAPI.</div>';}
function mission(){const p=run.runs[1].summary,b=run.runs[0].summary,c=run.config;const criticalDemand=p.criticalLoad;
return `<div class="mission-grid">${controls()}<div class="results"><div class="run-meta"><span class="pill pink">${scenarios[c.scenario]}</span><span>${c.days} days · ${span(c.days)} · ERA5 weather</span></div><div class="metrics">${metric('Fuel at mission end',fmt(p.fuelRemaining),'L',`${fmt(p.fuelUsed)} L consumed`,'pink-metric')}${metric('Critical demand served',fmt(100*(1-p.criticalUnserved/criticalDemand),2),'%',`${p.criticalHours} hours with critical shortfall`)}${metric('All unmet demand',fmt(p.unserved,1),'kWh','Includes every load priority')}${metric('Battery at mission end',fmt(p.endSoc,1),'%',`${fmt(p.endEnergy,1)} kWh stored`)}</div><section class="panel"><div class="panel-title"><div><h2>Fuel through the mission</h2><p>Remaining fuel against a straight-line mission budget</p></div><span class="pill">${c.days}-DAY HORIZON</span></div>${chart([{name:'Tuned rules',values:[c.fuel,...run.runs[0].rows.map(r=>r.fuelRemaining)]},{name:run.runs[1].controller,values:[c.fuel,...run.runs[1].rows.map(r=>r.fuelRemaining)]},{name:'Budget trajectory',values:[c.fuel,0],dash:true,color:'#b4bdcb'}],{labels:['Day 0',`Day ${c.days}`]})}</section><section class="panel"><div class="panel-title"><div><h2>Same mission. Two controllers.</h2><p>Read fuel use together with service and the battery end state.</p></div></div><div class="table-scroll"><table><thead><tr><th>Controller</th><th>Fuel used</th><th>Unmet demand</th><th>Critical unmet</th><th>End battery</th></tr></thead><tbody>${run.runs.map((r,i)=>`<tr class="${i?'highlight':''}"><th><i class="table-dot" style="background:${palette[i]}"></i>${r.controller}</th><td>${fmt(r.summary.fuelUsed)} L</td><td>${fmt(r.summary.unserved,1)} kWh</td><td>${fmt(r.summary.criticalUnserved,1)} kWh</td><td>${fmt(r.summary.endEnergy,1)} kWh</td></tr>`).join('')}</tbody></table></div><div class="comparison-note">${b.fuelUsed?p.fuelUsed<=b.fuelUsed?`Reported fuel use is ${fmt(100*(b.fuelUsed-p.fuelUsed)/b.fuelUsed,1)}% lower in this run.`:`Reported fuel use is ${fmt(100*(p.fuelUsed-b.fuelUsed)/b.fuelUsed,1)}% higher in this run.`:'No baseline fuel was consumed.'} Ending battery energies differ by ${fmt(Math.abs(p.endEnergy-b.endEnergy),1)} kWh. Python and browser fuel curves, battery efficiencies and allowed generator operation differ; this comparison does not establish controller savings.</div></section></div></div>`;}
function selector(){return `<label class="controller-select">Controller<select id="controller">${run.runs.map((r,i)=>`<option value="${i}" ${selected===i?'selected':''}>${r.controller}</option>`).join('')}</select></label>`;}
function dispatchView(){const rr=run.runs[selected],r=rr.rows[hour],c=run.config,dayStart=Math.floor(hour/24)*24,day=rr.rows.slice(dayStart,dayStart+24);const batteryAvailable=Math.min(c.batteryPower,Math.max(0,r.energy-c.battery*.15)*(rr.controller==='Python MILP'?Math.sqrt(.9):.95));const capacity=r.fuelRemaining>35?(rr.controller==='Python MILP'?(r.largeAvailable?185:60):(r.largeAvailable?125:60)):0;const headroom=Math.max(0,capacity+r.pv+r.wind+batteryAvailable-r.load);
 return `<div class="panel hour-panel"><div class="panel-title"><div><h2>Dispatch timeline</h2><p>Actual measurements and decisions, at one-hour resolution</p></div>${selector()}</div><div class="hour-control"><button id="prevHour" class="secondary" aria-label="Previous hour" ${hour===0?'disabled':''}>←</button><label for="hour">Day ${Math.floor(hour/24)+1}<strong>${String(hour%24).padStart(2,'0')}:00</strong></label><input aria-label="Mission hour" id="hour" type="range" min="0" max="${rr.rows.length-1}" value="${hour}"><button id="nextHour" class="secondary" aria-label="Next hour" ${hour===rr.rows.length-1?'disabled':''}>→</button><span>Hour ${hour} / ${rr.rows.length-1}</span></div></div><div class="dispatch-grid"><section class="panel"><div class="panel-title"><h2>Power balance</h2><span class="pill ${r.disruption?'pink':''}">${r.disruption?'DISRUPTION ACTIVE':'MEASURED HOUR'}</span></div><div class="power-grid">${[['Solar',r.pv,'kW','sun'],['Wind',r.wind,'kW','wind'],[r.generator?`${r.generator} kW diesel`:'Diesel off',r.generatorPower,'kW','diesel'],[r.batteryPower>=0?'Battery discharge':'Battery charge',Math.abs(r.batteryPower),'kW','battery']].map(([l,v,u,cl])=>`<div class="power-item ${cl}"><span>${l}</span><strong>${fmt(v,1)} <small>${u}</small></strong></div>`).join('')}</div><div class="load-balance"><span>Station demand<strong>${fmt(r.load,1)} kW</strong></span><span>Served<strong>${fmt(r.load-r.unserved,1)} kW</strong></span><span>Curtailed<strong>${fmt(r.curtailed,1)} kW</strong></span></div><div class="dispatch-reason"><span>DISPATCH EXPLANATION</span><p>${esc(r.reason)}</p>${r.replanned?'<small>Planner refreshed at this hour.</small>':''}</div></section><section class="panel"><div class="panel-title"><h2>Reserve, clean air & load priorities</h2></div><div class="soc-row"><span>Battery state of charge</span><strong>${fmt(r.soc,1)}%</strong></div><div class="battery-meter"><span style="width:${r.soc}%"></span></div><p class="muted">Operating band 15–95% · ${rr.controller==='Python MILP'?`Reserve ${fmt(r.reserveReq,1)} kW`:`Target ${25+c.risk*10}%`}</p><div class="reserve-values"><span>Stored energy<strong>${fmt(r.energy,1)} kWh</strong></span><span>Instantaneous headroom<strong>${fmt(headroom,1)} kW</strong></span></div><p class="tiny">Headroom is a one-hour capacity estimate, not a reliability guarantee.</p>${rr.controller==='Python MILP'?`<p class="muted">Reserve shortfall: ${fmt(r.reserveShortfall||0,1)} kW. Clean-air window: ${r.cleanAirSensitive?'sensitive':'clear'} · penalty ${fmt(r.cleanAirPenalty||0)} L-equivalent per generator-hour. ${r.dieselAvoided?'Diesel stayed off in this sensitive hour.':r.dieselDiscouraged?'Diesel was discouraged; reliability takes priority.':'No contamination penalty this hour.'}</p>`:''}${[['Critical',r.criticalLoad,r.criticalUnserved,'science and life safety'],['Essential',r.essentialLoad,r.essentialUnserved,'heating and water'],['Domestic',r.domesticLoad,r.domesticUnserved,'galley, workshop, personal']].map(([n,l,u,what])=>`<div class="priority-row"><span>${n} <small>${fmt(l,1)} kW · ${what}</small></span><b class="${u>1e-6?'bad':'good'}">${u>1e-6?fmt(u,1)+' kWh unmet':'Fully served'}</b></div>`).join('')}</section></div><section class="panel"><div class="panel-title"><div><h2>Day ${Math.floor(hour/24)+1} · Hourly dispatch</h2><p>Positive battery power supplies load. Negative power charges the battery.</p></div></div>${chart([{name:'Demand',values:day.map(r=>r.load),color:'#33445a'},{name:'Renewables',values:day.map(r=>r.pv+r.wind),color:'#5aa7d8'},{name:'Diesel',values:day.map(r=>r.generatorPower),color:'#e07a5f'},{name:'Battery',values:day.map(r=>r.batteryPower),color:'#8d7fd8'}],{unit:'kW',labels:['00:00',`${String(day.length-1).padStart(2,'0')}:00`]})}</section><div class="dispatch-grid"><section class="panel"><div class="panel-title"><h2>Fuel allowance & carry-forward</h2></div><div class="reserve-values"><span>Remaining tank<strong>${fmt(r.fuelRemaining)} L</strong></span><span>Revised daily allowance<strong>${fmt(r.dailyAllowance)} L/day</strong></span></div><p>Balance against cumulative starting allowance: <b class="${r.budgetRemaining<0?'bad':'good'}">${r.budgetRemaining>=0?'+':''}${fmt(r.budgetRemaining)} L</b></p><p class="muted">Unused allowance carries forward. A negative balance means spending ahead of the original budget. This is advisory, not a hard cap.</p></section><section class="panel"><div class="panel-title"><h2>Renewable planning inputs</h2><span class="pill">${rr.controller==='Python MILP'?'QUANTILE FORECAST':'PERSISTENCE'}</span></div><div class="reserve-values"><span>Expected renewables<strong>${fmt(r.forecastExpected,1)} kW</strong></span><span>Planning band<strong>${fmt(r.forecastLow,1)}–${fmt(r.forecastHigh,1)} kW</strong></span></div><p class="muted">Actual renewable output: ${fmt(r.pv+r.wind,1)} kW. ${rr.controller==='Python MILP'?`Method: ${esc(r.forecastMethod||'legacy client series')}. Forecast error (actual minus p50): ${fmt(r.forecastErrorRenewable||0,1)} kW renewable, ${fmt(r.forecastErrorLoad||0,1)} kW load.`:''} ${rr.controller==='Python MILP'?'MILP executes the measured hour and plans future hours from backend p10/p50/p90 forecasts. Synthetic NWP comes from lead-degraded ERA5.':'Forecast: wind as last measured, solar as the same hour yesterday.'} ${rr.controller==='Python MILP'?'Reserve comes from load upside, renewable downside and a configured contingency, with a disclosed cap.':'The band is a stated planning margin (10% at issue, widening to 30% at 36 hours), not a measured error.'}</p></section></div>`;}
function resilience(){const c=run.config,e=run.event,p=run.runs[1].summary,rr=run.runs[selected];const windowText=`Day ${Math.floor(e.start/24)+1}, ${String(e.start%24).padStart(2,'0')}:00 → hour ${e.end}`;const day=rr.rows.slice(0,24);let windows=[];for(let i=0;i<=day.length-4;i++){const a=day.slice(i,i+4);windows.push({h:i,score:a.reduce((s,r)=>s+r.forecastLow-r.load,0)/4});}windows.sort((a,b)=>b.score-a.score);const win=windows[0];
return `<div class="lab-intro"><div><h2>One station. Four operating conditions.</h2><p>Choose a stress test to run both controllers with the current station settings.</p></div><span class="pill">ERA5 · MAITRI 2023</span></div><div class="scenario-grid">${[['normal','01','Polar winter','Real weather at Maitri from 1 May 2023, with the station as configured.'],['blizzard','02','Four-day blizzard','Solar and wind drop to zero for 96 hours, placed at the mission\'s highest demand.'],['failure','03','Generator failure','The 125 kW generator is out for 48 hours where demand most exceeds wind and solar. The planner re-plans at once.'],['miss','04','Forecast misses a lull','Wind falls to 3% for 48 hours at its usually strongest stretch, while the forecast still expects normal wind.']].map(([id,no,name,desc])=>`<article class="panel scenario ${c.scenario===id?'chosen':''}"><span class="scenario-no">${no}</span><h3>${name}</h3><p>${desc}</p><button class="${c.scenario===id?'primary':'secondary'}" data-scenario="${id}" ${busy?'disabled':''}>${c.scenario===id?'Run again':'Run stress test'} →</button></article>`).join('')}</div><section class="panel"><div class="panel-title"><div><h2>Current result · ${scenarios[c.scenario]}</h2><p>${c.scenario==='normal'?'No injected disruption.':`Disruption window: ${windowText} (${e.end-e.start} hours).`}</p></div><button id="inspectEvent" class="secondary">Inspect ${c.scenario==='normal'?'dispatch':'disruption'} →</button></div><div class="table-scroll"><table><thead><tr><th>Controller</th><th>Critical lost</th><th>Essential lost</th><th>Domestic lost</th><th>Fuel left</th><th>First critical shortfall</th></tr></thead><tbody>${run.runs.map((x,i)=>{const m=x.summary;return `<tr class="${i?'highlight':''}"><th><i class="table-dot" style="background:${palette[i]}"></i>${x.controller}</th><td class="${m.criticalUnserved>1e-6?'bad':'good'}">${fmt(m.criticalUnserved,1)} kWh</td><td>${fmt(m.essentialUnserved,1)} kWh</td><td>${fmt(m.domesticUnserved,1)} kWh</td><td>${fmt(m.fuelRemaining)} L</td><td>${m.firstCriticalHour===null?'None':`Day ${Math.floor(m.firstCriticalHour/24)+1}, ${String(m.firstCriticalHour%24).padStart(2,'0')}:00`}</td></tr>`;}).join('')}</tbody></table></div><div class="comparison-note">Same weather, same station, same disruption for both controllers. Shortages are shed in order: domestic first, then essential, critical last.</div></div></section><div class="dispatch-grid"><section class="panel"><div class="panel-title"><h2>Sampling-window advisory</h2><span class="pill">DAY 1</span></div><strong class="window-time">${String(win.h).padStart(2,'0')}:00–${String(win.h+4).padStart(2,'0')}:00</strong><p>Highest four-hour average renewable margin in the first day's forecast.</p><div class="note">Margin before diesel and battery: ${fmt(win.score,1)} kW. ${win.score<0?'Renewables alone do not cover station load in this window.':'The forecast suggests surplus renewables.'} This advisory does not add or reschedule a real sampling load.</div></section><section class="panel"><div class="panel-title"><h2>What the experiment demonstrates</h2></div><ul class="clean-list"><li>Resource changes produce new dispatch and fuel trajectories.</li><li>Load priorities determine who loses power first.</li><li>Generator availability constrains the plan.</li><li>Forecast error can reduce reserve and create shortages.</li><li>Every reported result can be exported and reproduced.</li></ul></section></div>`;}
function model(){return `<div class="model-layout"><section class="panel model-summary"><div class="eyebrow">WORKING PROTOTYPE · REAL WEATHER</div><h2>Real Antarctic weather.<br>Every decision on screen.</h2><p>Weather is ERA5 reanalysis for India's Maitri station, from 1 May 2023. Solar, wind and station demand come from the HIMSHAKTI engine's physics model of the station on that weather. Change the station and both controllers re-run on exactly the same hours.</p><div class="model-facts"><span><strong>24–36 hours</strong>Backend horizon</span><span><strong>1 hour</strong>Connected refresh</span><span><strong>3 tiers</strong>Load priority</span><span><strong>FastAPI</strong>MILP with browser fallback</span></div></section><section class="panel"><h2>Calculation method</h2><p>Run simulation requests backend quantile forecasts and a Python MILP over 24 hours (up to 36 supported), executes the current measured hour, then replans. Native LightGBM artifacts are trained offline on 2019–2022 station twins and loaded once. Missing artifacts use an explicitly labeled statistical fallback. Future load and renewable inputs use p50; reserve adds load p90−p50, renewable p50−p10 and a configured contingency/cap. Forecast wind direction and speed activate a soft clean-air penalty; critical reliability takes priority. The MILP enforces a hard physical tank limit separately from the soft seasonal allowance, and carries generator elapsed on/off hours. SOC and fuel also carry forward. Battery efficiency is √0.90 per direction and both diesel units may run. Domestic maps to sheddable and deferrable is zero. Synthetic NWP is lead-degraded ERA5, not operational telemetry. The browser reserve selector affects the retained fallback only. The formulas below describe that fallback.</p><details open><summary>Energy balance & physical limits</summary><p>Solar + wind + diesel + battery discharge = served demand + battery charge + curtailment. Every interval is one hour, so kW × 1 h = kWh.</p><p>Battery energy follows E(next) = E + 0.95 × charge − discharge / 0.95. Capacity is limited to 15–95% state of charge, with a shared charge/discharge power limit.</p><p>One 60 kW or 125 kW diesel unit can operate. Each has a 30% minimum load. Assumed fuel curves are 2.1 + 0.24P L/h (60 kW) and 3.5 + 0.25P L/h (125 kW). The tank cannot go below zero.</p></details><details><summary>Rules and forecast planner</summary><p>Rules react to measured demand, renewable output and battery thresholds. The planner uses a width-14 beam search with seven generator actions, up to 36 hours ahead. It executes six actions before planning again; a detected change in generator availability triggers an earlier refresh. A protection layer underneath starts the smallest suitable generator if the measured shortfall exceeds what the plan and the battery can supply, then re-plans.</p><p>Critical, essential and domestic shortfalls incur weighted penalties of 10,000,000, 100,000 and 10,000 per kWh. Fuel scarcity, starts and battery reserve add smaller costs. This is approximate search, not MILP or a proof of optimality. Final battery energy is disclosed rather than forced equal between controllers.</p></details><details><summary>Weather, uncertainty and disruption assumptions</summary><p>Weather is hourly ERA5 reanalysis at Maitri (-70.75, 11.75): temperature, wind and sunlight. Solar uses a plane-of-array model at 70° tilt with snow cover on the panels; wind uses the turbine power curve corrected for cold, dense air and blade icing. Output scales with the solar and wind capacity you enter. Station demand is built from headcount, building heat loss at the measured temperature, snow melting for water and a constant 20 kW science and life-safety load.</p><p>Forecasts are persistence from that record: wind as last measured when the plan is made, solar and demand as the same hour the day before. The band widens from 10% to 30% over 36 hours as a planning margin. In the missed-lull test the forecast keeps expecting normal wind. Faults are detected at the hour boundary; current availability is assumed over the forecast horizon.</p><p>Each stress test is placed at the most demanding point of the mission: the blizzard at the highest-demand 96 hours, the generator failure where demand most exceeds wind and solar, the lull where wind is normally strongest. Demand shares come from the station model: about a quarter critical (science and life safety), two-thirds essential (heat and water), the rest domestic. The connected MILP enforces minimum up/down time; the browser fallback does not. There is no subhour frequency model, heat network, ramp rate, start delay, cold battery derating or hardware control.</p></details><details><summary>Fuel survivability and flexible sampling</summary><p>The initial daily allowance is starting fuel divided by mission days. Cumulative unused allowance carries forward, and the revised allowance is remaining fuel divided by remaining mission time. Fuel scarcity affects the planner's cost; the allowance is advisory, not a hard constraint. The default 6,300 L tank is set just under what the rule-based controller burns in an ordinary 30-day winter, so fuel is genuinely scarce.</p><p>A four-hour sampling-window suggestion uses first-day lower-range renewable margin. It is an advisory only. A real flexible-load scheduler and operational reserve validation remain final-build work.</p></details></section><section class="panel"><div class="panel-title"><h2>Build guide coverage</h2><a href="./BUILD_GUIDE.md" download>Full guide ↓</a></div><div class="table-scroll"><table><thead><tr><th>Capability</th><th>This prototype</th><th>Full engine</th></tr></thead><tbody>${[['Station resources','Editable solar, wind, battery, fuel and duration','Calibrated station ratings and load profiles'],['Weather','ERA5 reanalysis, Maitri 2023, hourly','ERA5 2015-2023 with station observations where available'],['Forecasts','Backend LightGBM quantiles with labeled statistical fallback; browser persistence offline','Held-out evaluation of calibrated uncertainty'],['Scheduling','Connected: 24-hour MILP / hourly refresh; browser beam search offline','Formal MILP with PuLP + HiGHS'],['Resilience','Blizzard, fault and missed-lull scenarios at the most demanding point','Held-out years and real fault validation'],['Inspection','Power, fuel budget, reserve, priorities, explanations','Operator validation and real flexible-load constraints'],['Artifacts','Computed hourly CSV, full JSON and Markdown','Validated benchmark results and final submission recording']].map(a=>`<tr>${a.map((s,i)=>`<${i?'td':'th'}>${s}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Submission & source material</h2><p>The six-slide deck describes the full HIMSHAKTI engine: Python, ERA5, LightGBM quantile forecasts and a MILP optimiser. This dashboard connects to that Python pipeline and retains the original browser planner as an offline fallback.</p><p>Connected dispatch is computed by the Python backend; measured station inputs and the browser baseline use the 2023 station record.</p><ul class="clean-list"><li>GitHub-ready source, deployment configuration and meaningful simulation checks are included.</li><li>The companion Markdown includes a narrated demo script and six-slide speaking outline.</li><li>Add team ID, roles, the final six-slide PPT and your recorded application demo to the submission repository.</li><li>Confirm organizer requirements, deadline and judge access before submitting.</li></ul><div class="note">This is decision-support software for a hackathon demonstration. It does not control station equipment.</div></section></div>`;}
function readInputs(){const c={...config};for(const [k] of fields){if(!$('#'+k).checkValidity()||$('#'+k).value.trim()==='')throw Error(`Enter a valid ${k}.`);c[k]=Number($('#'+k).value);}c.scenario=$('#scenario').value;c.risk=Number($('#risk').value);return validateConfig(c);}
function bindSurface(){if($('#simulate')){$('#simulate').onclick=()=>{try{config=readInputs();startRun();}catch(e){error=e.message;status();}};$('#reset').onclick=()=>{config={...defaults};dirty=true;error='';surface();};for(const id of [...fields.map(x=>x[0]),'scenario','risk'])$('#'+id).onchange=()=>{try{config=readInputs();error='';}catch(e){error=e.message;}dirty=true;status();};}if($('#cancel'))$('#cancel').onclick=cancelRun;
 if($('#controller'))$('#controller').onchange=e=>{selected=Number(e.target.value);surface();};if($('#hour')){$('#hour').oninput=e=>{const h=Number(e.target.value);document.querySelector('.hour-control label').innerHTML=`Day ${Math.floor(h/24)+1}<strong>${String(h%24).padStart(2,'0')}:00</strong>`;};$('#hour').onchange=e=>{hour=Number(e.target.value);surface();$('#hour').focus();};}if($('#prevHour'))$('#prevHour').onclick=()=>{hour=Math.max(0,hour-1);surface();};if($('#nextHour'))$('#nextHour').onclick=()=>{hour=Math.min(run.runs[0].rows.length-1,hour+1);surface();};document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{config={...config,scenario:b.dataset.scenario};startRun();});if($('#inspectEvent'))$('#inspectEvent').onclick=()=>{hour=run.config.scenario==='normal'?0:run.event.start;tab='dispatch';shell();};}
async function startRun(c=config){
 if(busy)throw Error('A simulation is already running.');
 config=validateConfig(c);const snapshot={...config};busy=true;error='';
 const abort=new AbortController();activeAbort=abort;surface();
 return new Promise((resolve,reject)=>{activeReject=reject;
  const progress=m=>{if($('#progress'))$('#progress').textContent=`${m.controller} · Day ${Math.floor(m.hour/24)+1} of ${snapshot.days}`;};
  function fail(msg){if(abort.signal.aborted)return;error=msg;busy=false;worker?.terminate();worker=null;activeReject=null;activeAbort=null;surface();reject(Error(msg));}
  try{worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
   worker.onmessage=async e=>{const m=e.data;
    if(m.type==='progress')progress(m);
    else if(m.type==='result'){
     worker.terminate();worker=null;let result;
     try{result=await optimiseMission(snapshot,m.run.runs[0],progress,{signal:abort.signal});}
     catch(e){if(abort.signal.aborted)return;result={...m.run,execution:'browser-fallback',warning:`${e.message} Showing the browser simulator fallback; these are not MILP results.`};}
     if(abort.signal.aborted)return;
     run=result;busy=false;dirty=JSON.stringify(config)!==JSON.stringify(snapshot);hour=0;activeReject=null;activeAbort=null;shell();resolve({execution:run.execution,warning:run.warning,runs:run.runs.map(r=>({controller:r.controller,...r.summary}))});
    }else fail(m.message);
   };
   worker.onerror=e=>fail(e.message||'The simulation could not start. Serve the app over HTTP and try again.');worker.postMessage(snapshot);
  }catch(e){fail(e.message);}
 });
}
function cancelRun(){activeAbort?.abort();activeAbort=null;worker?.terminate();worker=null;busy=false;error='Simulation cancelled. The previous completed result is unchanged.';activeReject?.(Error('Cancelled'));activeReject=null;surface();}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadUrl(url){const a=document.createElement('a');a.href=url;a.download='Pink_Monster_Build_Guide.md';a.click();}
window.addEventListener('unhandledrejection',e=>{if(error)e.preventDefault();});
shell();
try{const response=await fetch('./data/default-run.json');if(!response.ok)throw Error('Default run is unavailable. You can run a fresh simulation.');run=await response.json();shell();}catch(e){error=e.message;surface();}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_mission_results',description:'Read the completed polar energy simulation and its configuration.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({execution:run?.execution,warning:run?.warning,config:run?.config,runs:run?.runs.map(r=>({controller:r.controller,...r.summary})),busy,dirty})},{name:'run_mission_simulation',description:'Run both controllers with the given station settings and update visible results.',inputSchema:{type:'object',properties:Object.fromEntries(Object.entries(limits).map(([k,[minimum,maximum]])=>[k,{type:k==='days'?'integer':'number',minimum,maximum}] ).concat([['scenario',{type:'string',enum:Object.keys(scenarios)}]])),additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!(k in defaults)))throw Error('Invalid configuration.');return startRun(validateConfig({...config,...input}));}}];for(const t of tools)try{await document.modelContext.registerTool(t,{signal:lifecycle.signal});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

// UI polish only. Runs after each render; animates when the page, run, scenario or
// selected controller changes, and stays still while scrubbing the hour slider. Uses the
// vendored Motion browser build (window.Motion) when present and skips everything if the
// visitor prefers reduced motion. Values are restored exactly when each animation ends.
// state lives on the function: function declarations are hoisted, a module-level let is not
function enhance(){const s=$('#surface');if(!s||!run)return;const key=[tab,run.createdAt,run.config&&run.config.scenario,selected].join('|');const fresh=key!==enhance.last;enhance.last=key;s.classList.toggle('settled',!fresh);const M=window.Motion;if(!fresh||!M||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 M.animate(s.querySelectorAll('.panel,.metric'),{y:[12,0]},{duration:.5,delay:M.stagger(.035),ease:[.16,1,.3,1]});
 s.querySelectorAll('.metric strong').forEach(el=>{const n=el.firstChild;if(!n||n.nodeType!==3)return;const txt=n.nodeValue;const target=Number(txt.trim().replace(/,/g,''));if(!Number.isFinite(target)||target===0)return;const d=(txt.trim().split('.')[1]||'').length;M.animate(0,target,{duration:1.1,ease:[.16,1,.3,1],onUpdate:v=>{n.nodeValue=v.toLocaleString('en-IN',{minimumFractionDigits:d,maximumFractionDigits:d});},onComplete:()=>{n.nodeValue=txt;}});});}
